# owner: platform
"""Seating charts: students sorted by name, row by row."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _name(s: Student) -> str:
    return f"{s.last_name}, {s.first_name}"


def _line(num: int, row: List[Student]) -> str:
    return f"Row {num}: " + " | ".join(map(_name, row))


def _chunks(items: list, size: int) -> list:
    return [items[i:i + size]
            for i in range(0, len(items), size)]


def seating_rows(students: List[Student], seats: int):
    """One line per row, sorted by last name."""
    if seats <= 0 or not students:
        raise ProjectError("need students and seats")
    rows = _chunks(sorted(students, key=_name), seats)
    return [_line(n, r) for n, r in enumerate(rows, 1)]

